import{_ as l,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-09-24 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-09-24 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-09-24T00:00:00.000Z","updated":"2019-10-01T00:00:00.000Z","tags":["Ceph","分布式存储","OSD","性能测试","项目管理"],"categories":["会议纪要","存储技术"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-24_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-09-24_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-09-24_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function n(p,i,s,_,a,g){return e(),t("div",null,[...i[0]||(i[0]=[o("<p>会议纪要</p><p><strong>会议时间</strong>： 2019年9月24日</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及问题讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、项目进展</strong></p><ol><li><p><strong>Riddick Spear计划和Ackerson计划</strong>：</p><ul><li>正在撰写，旨在支持写入操作，定义项目范围和估算时间线。</li><li>计划本周完成并提交给利益相关者。</li></ul></li><li><p><strong>性能测试</strong>：</p><ul><li>对Ceph存储性能进行了测试，发现了一些问题，将进行进一步调查和修复。</li></ul></li><li><p><strong>Riddick pantry writer问题</strong>：</p><ul><li>存在返回响应问题，需要进一步调试，尝试使用未修改的Constantine虚拟版本进行调试。</li></ul></li><li><p><strong>Ceph OSD操作接口</strong>：</p><ul><li>正在修改，以支持状态错误和状态迁移，提高代码可读性。</li></ul></li><li><p><strong>Ceph恢复机制</strong>：</p><ul><li>正在重构，以创建更清晰的接口，提高异步操作处理效率。</li></ul></li></ol><p><strong>二、讨论的主要议题</strong></p><ol><li><p><strong>Ceph经典OSD与Crimson接口整合</strong>：</p><ul><li>讨论如何整合接口，简化代码并提高可读性，决定使用状态机来封装异步操作。</li></ul></li><li><p><strong>Ceph调度器与Gemini Cook集成</strong>：</p><ul><li>讨论如何集成，以更有效地处理异步操作，决定研究集成方案。</li></ul></li><li><p><strong>Ceph性能测试</strong>：</p><ul><li>讨论性能测试的重要性，决定开展更多测试以评估性能。</li></ul></li></ol><p><strong>三、决定的事项</strong></p><ol><li>完成Riddick Spear和Ackerson计划。</li><li>解决Riddick pantry writer问题。</li><li>修改Ceph OSD操作接口。</li><li>重构Ceph恢复机制。</li><li>研究Ceph调度器与Gemini Cook的集成方案。</li><li>开展更多Ceph性能测试。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>项目负责人推进Riddick Spear和Ackerson计划的编写。</li><li>技术人员调试Riddick pantry writer问题。</li><li>技术人员修改Ceph OSD操作接口和重构Ceph恢复机制。</li><li>技术人员研究Ceph调度器与Gemini Cook的集成方案。</li><li>技术人员开展更多Ceph性能测试。</li></ol>",13)])])}const C=l(r,[["render",n]]);export{d as __pageData,C as default};
